import{_ as e,o as r,c as a,a5 as n}from"./chunks/framework.bIR-4glx.js";const g=JSON.parse('{"title":"Job-search English Evidence Card: From Job Description to Unfamiliar Follow-up","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/interview-evidence.en.md","filePath":"public/downloads/worksheets/interview-evidence.en.md","lastUpdated":1795488252000}'),i={name:"public/downloads/worksheets/interview-evidence.en.md"};function o(d,t,l,s,h,c){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="job-search-english-evidence-card-from-job-description-to-unfamiliar-follow-up" tabindex="-1">Job-search English Evidence Card: From Job Description to Unfamiliar Follow-up <a class="header-anchor" href="#job-search-english-evidence-card-from-job-description-to-unfamiliar-follow-up" aria-label="Permalink to &quot;Job-search English Evidence Card: From Job Description to Unfamiliar Follow-up&quot;">​</a></h1><p>This card does not decide whether you are suited to overseas work or promise an interview result. It answers a narrower question: <strong>under this role and process, can I deliver my real ability in English?</strong></p><p>Copy it into a private note. Job descriptions, recruiting email, take-home tasks, company code, customer information, and interview recordings may contain confidential or personal information. Preserve only the minimum material you have a right to use, and obtain necessary consent before recording.</p><h2 id="_1-role-and-process" tabindex="-1">1. Role and Process <a class="header-anchor" href="#_1-role-and-process" aria-label="Permalink to &quot;1. Role and Process&quot;">​</a></h2><p>Role title and public link:<br> Application deadline or interview date:<br> Work mode: remote / hybrid / on-site<br> Primary time zones and collaboration mode:<br> Known interview stages:<br> Explicit language requirement:<br> Recruiting rules still unknown:</p><h2 id="_2-role-language-map" tabindex="-1">2. Role Language Map <a class="header-anchor" href="#_2-role-language-map" aria-label="Permalink to &quot;2. Role Language Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role fact</th><th>Language task</th><th>Current evidence</th><th>Risk</th><th>Build evidence in two weeks?</th></tr></thead><tbody><tr><td></td><td>recruiter communication / project explanation / technical follow-up / behavioural question / async writing / customer communication</td><td></td><td>high / medium / low</td><td></td></tr></tbody></table><p>Can complete independently:<br> Can complete with preparation:<br> Depends on prompts or translation:<br> Has no sample:<br> One highest-risk gap to repair:</p><h2 id="_3-complete-baseline" tabindex="-1">3. Complete Baseline <a class="header-anchor" href="#_3-complete-baseline" aria-label="Permalink to &quot;3. Complete Baseline&quot;">​</a></h2><p>Date:<br> Preparation time:<br> Visible support: none / outline / full script<br> Tools: none / dictionary / captions / AI / other<br> Recording and text location:</p><table tabindex="0"><thead><tr><th>Stage</th><th style="text-align:right;">Time</th><th>Acceptance</th><th>Independent result</th><th>Main error</th></tr></thead><tbody><tr><td>Role-relevant introduction</td><td style="text-align:right;">2 min</td><td>Present work, evidence, direction</td><td></td><td></td></tr><tr><td>Project explanation</td><td style="text-align:right;">5 min</td><td>Context, responsibility, trade-off, result, unknown</td><td></td><td></td></tr><tr><td>Unfamiliar follow-up</td><td style="text-align:right;">3 questions</td><td>Understand, answer, or clarify</td><td></td><td></td></tr><tr><td>Asynchronous update</td><td style="text-align:right;">20 min</td><td>Progress, evidence, risk, next step, owner</td><td></td><td></td></tr><tr><td>Interaction repair</td><td style="text-align:right;">1 case</td><td>Repeat/confirm/thinking time/unknown boundary</td><td></td><td></td></tr></tbody></table><h2 id="_4-error-map" tabindex="-1">4. Error Map <a class="header-anchor" href="#_4-error-map" aria-label="Permalink to &quot;4. Error Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Segment/question</th><th>Type</th><th>Effect on the task</th><th>What to test next</th></tr></thead><tbody><tr><td></td><td>content / retrieval / listening / organisation / interaction / accuracy</td><td></td><td></td></tr></tbody></table><p>Largest problem that is not primarily English:<br> Language error that repeatedly changes key meaning:<br> Repair action worth preserving:</p><h2 id="_5-real-story-bank" tabindex="-1">5. Real Story Bank <a class="header-anchor" href="#_5-real-story-bank" aria-label="Permalink to &quot;5. Real Story Bank&quot;">​</a></h2><p>Keep six lines rather than a full script:</p><p>Story name:<br> Situation and required task:<br> My specific responsibility:<br> Key action and trade-off:<br> Result, cost, and unknown:<br> What I would change now:<br> Evidence location:</p><table tabindex="0"><thead><tr><th>Story</th><th>Questions it can answer</th><th>Available after unfamiliar follow-up?</th><th>Fact/privacy check</th></tr></thead><tbody><tr><td></td><td>problem / failure / conflict / decision / feedback / stopping</td><td>yes / no</td><td></td></tr></tbody></table><h2 id="_6-listening-and-repair" tabindex="-1">6. Listening and Repair <a class="header-anchor" href="#_6-listening-and-repair" aria-label="Permalink to &quot;6. Listening and Repair&quot;">​</a></h2><p>Original question I did not understand:<br> Sentence used to request repetition or confirmation:<br> Meaning after restatement:<br> My answer:<br> How shared understanding was confirmed:</p><table tabindex="0"><thead><tr><th>Repair ability</th><th style="text-align:right;">Baseline 0–2</th><th style="text-align:right;">Day seven 0–2</th><th>Evidence</th></tr></thead><tbody><tr><td>Request a specific repetition</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Confirm scope</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Ask for thinking time</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Admit an unknown and give a verification step</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Summarise agreement and next action</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><h2 id="_7-asynchronous-writing-sample" tabindex="-1">7. Asynchronous Writing Sample <a class="header-anchor" href="#_7-asynchronous-writing-sample" aria-label="Permalink to &quot;7. Asynchronous Writing Sample&quot;">​</a></h2><p>Context:<br> Completed:<br> Evidence:<br> Blocked / risk:<br> Decision needed:<br> Owner and next update:</p><p>Ask one reader:</p><p>What happened:<br> What needs a decision:<br> Who continues and when:<br> Sentence that required guessing:</p><h2 id="_8-ai-and-integrity-record" tabindex="-1">8. AI and Integrity Record <a class="header-anchor" href="#_8-ai-and-integrity-record" aria-label="Permalink to &quot;8. AI and Integrity Record&quot;">​</a></h2><p>Tool and date:<br> Role it simulated:<br> Independent version submitted first:<br> Three problems it raised:<br> Feedback accepted/rejected and why:<br> Parallel result after closing the tool:<br> Stage where AI must be disclosed or is prohibited:<br> Confidential/personal information kept out:</p><p>Do not invent experience, numbers, or ownership. Do not use covert real-time prompting in a live interview without explicit permission.</p><h2 id="_9-fourteen-day-comparison" tabindex="-1">9. Fourteen-Day Comparison <a class="header-anchor" href="#_9-fourteen-day-comparison" aria-label="Permalink to &quot;9. Fourteen-Day Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time point</th><th>Condition</th><th style="text-align:right;">Task completion</th><th style="text-align:right;">Understanding/repair</th><th style="text-align:right;">Organisation/retrieval</th><th style="text-align:right;">Async writing</th><th>Evidence</th></tr></thead><tbody><tr><td>Day-one baseline</td><td>Unscripted, no AI</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Immediate revision</td><td>Feedback seen</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Day-seven retest</td><td>Parallel questions, original answer removed</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Day-fourteen transfer</td><td>New interviewer/order/role question</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><p>Score each 0–2: <code>0=not completed</code>, <code>1=partial or prompt-dependent</code>, <code>2=completed under the current condition</code>. Use only for one person&#39;s comparable tasks.</p><h2 id="_10-current-role-gates" tabindex="-1">10. Current Role Gates <a class="header-anchor" href="#_10-current-role-gates" aria-label="Permalink to &quot;10. Current Role Gates&quot;">​</a></h2><ul><li>[ ] At least three real stories remain available under changed wording.</li><li>[ ] Recruiter screen, project explanation, and unfamiliar follow-up can be completed.</li><li>[ ] Unclear questions produce clarification rather than guessing.</li><li>[ ] Repeated language errors do not change key meaning.</li><li>[ ] One usable asynchronous update can be written.</li><li>[ ] Confidentiality, recording, and AI boundaries are known.</li><li>[ ] Unknowns can be admitted with a verification method.</li><li>[ ] Equipment, time zone, and interview environment are checked.</li></ul><p>Current evidence most supports: apply and continue practising / repair one high-risk gap / defer this role<br> Evidence:<br> Conclusion I still cannot draw:<br> Smallest next task:<br> Next review date:</p><h2 id="_11-post-interview-close" tabindex="-1">11. Post-interview Close <a class="header-anchor" href="#_11-post-interview-close" aria-label="Permalink to &quot;11. Post-interview Close&quot;">​</a></h2><p>Actual questions:<br> Evidence of correct understanding:<br> Clarification that worked:<br> Story that failed to answer the question:<br> Structure that transferred:<br> Difficulty not caused primarily by English:<br> Recruiter feedback in original wording:<br> One variable to change:<br> Preparation to stop:</p><p>Related chapters: <a href="https://byoungd.github.io/up/en/threads/part-1/8-job-search-english" target="_blank" rel="noreferrer">Job-search English: Bring Ability into Interviews and Remote Work</a> | <a href="https://byoungd.github.io/up/en/templates/speaking-evidence" target="_blank" rel="noreferrer">Speaking Evidence Card</a> | <a href="https://byoungd.github.io/up/en/templates/writing-evidence" target="_blank" rel="noreferrer">Writing Evidence Card</a></p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/interview-evidence" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-09-02. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',39)])])}const b=e(i,[["render",o]]);export{g as __pageData,b as default};
